// 动员·回合累积（csx 行为引用样本）：友方回合开始 → 在场单位 +1/+1（修饰器来源＝宿主卡）。
Func<Orc.Cards.CardEventView, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{
    if (view.Player is not Orc.Game.Players.Player current
        || view.Host is not Orc.Game.Cards.CardBase ownerCard
        || !object.ReferenceEquals(ownerCard.Owner, current))
    {
        return; // 非该单位拥有者的回合开始：不处理
    }

    if (view.Host is not Orc.Game.Cards.UnitCard unit
        || !unit.TryGetData<Orc.Game.Cards.UnitStateData>(out var state)
        || state.IsDestroyed
        || state.Position is null)
    {
        return; // 未在场（未单位化/已死亡/无位置）：不获得
    }

    await unit.Modifiers.AddModifiersAsync(
        new Orc.Game.Cards.Modifier[]
        {
            new Orc.Game.Cards.AddModifier(Orc.Game.Cards.CardStatFields.Attack, 1, ownerCard),
            new Orc.Game.Cards.AddModifier(Orc.Game.Cards.CardStatFields.Defense, 1, ownerCard),
        },
        ct);
};
